from fractions import Fraction

def first_exceeding(t):
    """Smallest n with H_n = 1 + 1/2 + ... + 1/n > t."""
    total, n = 0.0, 0
    while total <= t:
        n += 1
        total += 1 / n
    return n

def telescoping_sum(n):
    """S_n of the series 1/(k(k+1)) as an exact Fraction."""
    return sum(Fraction(1, k * (k + 1)) for k in range(1, n + 1))
